.={
				  ID:                   val.id,
				  FileName:             val.fileName,
				  PathName:             val.pathName,
				  FileCatalogId:        val.fileCatalogId,
				  AnalysisResult:       function(status) {
				                           switch(status) {
				                                case 0:
				                                        return "Not yet available";
				                                        break;
				                                case 1:
				                                        return "File is clean";
				                                        break;
				                                case 2:
				                                        return "File is a potential threat";
				                                        break;
				                                case 3:
				                                        return "File is malicious";
				                                        break;
				                                default:
				                                        return "Not yet available"
				                           }
				                        }(val.analysisResult),
				  AnalysisStatus:       function(status) {
				                           switch(status) {
				                                case 0:
				                                        return "scheduled";
				                                        break;
				                                case 1:
				                                        return "submitted";
				                                        break;
				                                case 2:
				                                        return "processed";
				                                        break;
				                                case 3:
				                                        return "analyzed";
				                                        break;
				                                case 4:
				                                        return "error";
				                                        break;
				                                case 5:
				                                        return "cancelled";
				                                        break;
				                                default:
				                                        return "status is not yet available"
				                           }
				                        }(val.analysisStatus),
				  ConnectorId:          val.connectorId,
				  AnalysisTarget:       val.analysisTarget
				  ComputerId:           val.computerId,
				  DateModified:         val.dateModified,
				  DateCreated:          val.dateCreated,
				  Priority:             val.priority,
				  CreatedBy:            val.createdBy,
				  CreatedByUserId:      val.createdByUserId,

				}

.={

